import React from 'react';
import Navbar from '../components/Navbar';

const Dashboard = () => {
  return (
    <div className="bg-[#020617] min-h-screen text-white">
      <Navbar />
      <div className="p-8 space-y-6 max-w-3xl mx-auto">
        <h2 className="text-white uppercase text-sm font-bold border-b border-slate-900 pb-4">Mes cours en cours</h2>
        <div className="bg-slate-950 border border-slate-900 p-6 rounded-lg">
          <p className="text-white text-xs font-mono">Hacking Offensif</p>
          <div className="w-full bg-slate-900 h-2 mt-2 rounded"><div className="w-1/2 bg-blue-600 h-2 rounded"></div></div>
          <p className="text-[10px] text-slate-500 mt-2 font-mono">50% complété</p>
        </div>
      </div>
    </div>
  );
};
export default Dashboard;
